var SITE = 'https://raisingonpurpose.vercel.app';
function slugify(s) { return String(s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''); }
var LABELS = { 'intentional-parenting': 'Intentional Parenting', 'real-talk': 'Real Talk', 'toddler': 'Toddler Years', 'family-routines': 'Family Routines', 'printables': 'Printables' };
var TAGS = { 'intentional-parenting': '#gentleparenting', 'real-talk': '#honestmotherhood', 'toddler': '#toddlerlife', 'family-routines': '#familyroutines', 'printables': '#freeprintables' };
var rows = items.map(function (i) { return i.json; });
var queue = rows.filter(function (r) {
  var st = String(r['Status'] || '').toLowerCase().trim();
  var pinned = String(r['Pinned'] || '').toLowerCase().trim() === 'true';
  return st === 'done' && !pinned && r['Slug'] && r['Generated Title'];
});
if (!queue.length) { return []; }
queue.sort(function (a, b) { return String(a['Generated At'] || a['Date'] || 'z').localeCompare(String(b['Generated At'] || b['Date'] || 'z')); });
var r = queue[0];
var slug = String(r['Slug']).trim();
var cat = slugify(r['Category']) || 'family-routines';
var title = String(r['Generated Title']).trim();
var desc = String(r['Meta Description'] || r['Blog Post Topic'] || title).trim();
var cover = String(r['Image URL'] || '').trim();
if (cover.charAt(0) === '/') { cover = SITE + cover; }
var postUrl = SITE + '/' + cat + '/' + slug;
var pinUrl = SITE + '/api/pin?title=' + encodeURIComponent(title) + '&eyebrow=' + encodeURIComponent(LABELS[cat] || cat) + '&img=' + encodeURIComponent(cover);
if (cat === 'printables') { pinUrl = pinUrl + '&badge=' + encodeURIComponent('FREE PRINTABLE'); }
var text = desc + '\n\nRead the full post at the link.' + '\n\n#parenting #momlife #intentionalparenting ' + (TAGS[cat] || '#family');
return [{ json: { slug: slug, title: title, postUrl: postUrl, pinUrl: pinUrl, pinText: text, keyword: String(r['Keyword'] || '') } }];

var body = items[0].json;
if (body.errors) { throw new Error('Buffer API (orgs): ' + body.errors.map(function (e) { return e.message; }).join('; ')); }
var orgs = (body.data && body.data.account && body.data.account.organizations) || [];
if (!orgs.length) { throw new Error('No Buffer organizations found for this API key.'); }
var pin = $('Pick Next Pin').first().json;
var q = 'query GetChannels { channels(input: { organizationId: "' + orgs[0].id + '" }) { id name service } }';
return [{ json: {
  orgId: orgs[0].id, orgName: orgs[0].name,
  slug: pin.slug, title: pin.title, postUrl: pin.postUrl, pinUrl: pin.pinUrl, pinText: pin.pinText, keyword: pin.keyword,
  payload: JSON.stringify({ query: q })
} }];

var body = items[0].json;
if (body.errors) { throw new Error('Buffer API (channels): ' + body.errors.map(function (e) { return e.message; }).join('; ')); }
var list = (body.data && body.data.channels) || [];
var found = null;
for (var k = 0; k < list.length; k++) {
  if (String(list[k].service || '').toLowerCase() === 'pinterest') { found = list[k]; break; }
}
if (!found) { throw new Error('No Pinterest channel connected in Buffer. Connect it under Publishing > Channels first.'); }
var prev = $('Take Org + Build Channels Query').first().json;
var q = 'query GetBoards { channel(input: { id: "' + found.id + '" }) { metadata { ... on PinterestMetadata { boards { serviceId name } } } } }';
return [{ json: {
  channelId: found.id, channelName: found.name,
  slug: prev.slug, title: prev.title, postUrl: prev.postUrl, pinUrl: prev.pinUrl, pinText: prev.pinText, keyword: prev.keyword,
  payload: JSON.stringify({ query: q })
} }];

var body = items[0].json;
if (body.errors) { throw new Error('Buffer API (boards): ' + body.errors.map(function (e) { return e.message; }).join('; ')); }
var ch = (body.data && body.data.channel) || {};
var boards = (ch.metadata && ch.metadata.boards) || [];
if (!boards.length) { throw new Error('No boards found on the Pinterest channel. Create at least one board in Pinterest first.'); }
var prev = $('Take Pinterest Channel + Build Boards Query').first().json;
var query = 'mutation QueuePin($text: String!, $imageUrl: String!, $link: String!, $pinTitle: String!) {';
query = query + ' createPost(input: { channelId: "' + prev.channelId + '", text: $text, schedulingType: automatic, mode: addToQueue,';
query = query + ' assets: [{ image: { url: $imageUrl } }],';
query = query + ' metadata: { pinterest: { boardServiceId: "' + boards[0].serviceId + '", title: $pinTitle, url: $link } } }) {';
query = query + ' ... on PostActionSuccess { post { id text dueAt } } ... on MutationError { message } } }';
return [{ json: {
  slug: prev.slug, boardName: boards[0].name || boards[0].serviceId,
  payload: JSON.stringify({ query: query, variables: { text: prev.pinText, imageUrl: prev.pinUrl, link: prev.postUrl, pinTitle: prev.title } })
} }];
